mapper.select:
SELECT attempts,window_id,GREATEST(1,CEIL(#{windowSeconds}-MOD(UNIX_TIMESTAMP(),#{windowSeconds}))) AS retry_after_seconds
FROM login_entry_window
WHERE attempt_key=#{attemptKey}

mapper.update:
UPDATE login_entry_window
SET attempts=GREATEST(attempts-1,0)
WHERE attempt_key=#{attemptKey} AND window_id=#{windowId}
